    [VENDOR_ACTIVITY.TYPES.ORDER_UPDATE]: VENDOR_ACTIVITY.SEVERITIES.MEDIUM,
    [VENDOR_ACTIVITY.TYPES.ORDER_CANCEL]: VENDOR_ACTIVITY.SEVERITIES.HIGH,
    [VENDOR_ACTIVITY.TYPES.PAYMENT_RECEIVE]: VENDOR_ACTIVITY.SEVERITIES.HIGH,
    [VENDOR_ACTIVITY.TYPES.PAYMENT_SEND]: VENDOR_ACTIVITY.SEVERITIES.HIGH,
    [VENDOR_ACTIVITY.TYPES.SETTLEMENT]: VENDOR_ACTIVITY.SEVERITIES.MEDIUM,
    [VENDOR_ACTIVITY.TYPES.PROFILE_UPDATE]: VENDOR_ACTIVITY.SEVERITIES.LOW,
    [VENDOR_ACTIVITY.TYPES.PASSWORD_CHANGE]: VENDOR_ACTIVITY.SEVERITIES.HIGH,
    [VENDOR_ACTIVITY.TYPES.SETTINGS_UPDATE]: VENDOR_ACTIVITY.SEVERITIES.MEDIUM,
    [VENDOR_ACTIVITY.TYPES.SUPPORT_TICKET]: VENDOR_ACTIVITY.SEVERITIES.MEDIUM,
